//! The long alternations the rules use, generated by `scripts/extract_category_lists.py`.

const DATA: &str = include_str!("../../data/category_lists.tsv");

/// A list's text. A name that isn't there is a bug the first test finds.
pub(crate) fn list(name: &str) -> &'static str {
    DATA.lines()
        .filter(|l| !l.starts_with('#'))
        .filter_map(|l| l.split_once('\t'))
        .find(|(k, _)| *k == name)
        .map(|(_, v)| v)
        .unwrap_or_else(|| panic!("no category list {name}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_list_is_there_and_has_no_empty_alternative() {
        for name in [
            "JACQUIE_ET_MICHEL",
            "KNOWN_STUDIOS",
            "ADULT_KEYWORDS",
            "VR_SITES",
            "GENERIC_VR_SITE",
            "VR_DEVICES",
            "PC_GROUPS",
            "PC_KEYWORDS",
            "FOREIGN_LANGUAGES",
            "LANGUAGE_CODES",
            "SPORTS_MARKER_REGEX",
            "SPORTS_EVENT_CONTEXT_REGEX",
            "ANIME_GROUPS_REGEX",
        ] {
            let text = list(name);
            assert!(!text.starts_with('|') && !text.ends_with('|') && !text.contains("||"), "{name}");
        }
        assert!(list("KNOWN_STUDIOS").contains("Jacquie"));
    }
}
